package com.dpworld.fms.integration.rabbitmq;
import org.springframework.amqp.core.*; import org.springframework.context.annotation.*;
@Configuration public class RabbitTopology { public static final String BUSINESS="dpwfms.business.v1",DLX="dpwfms.dlx.v1",DISPATCH="dpwfms.dispatch.commands.q"; @Bean Declarables topology(){var business=new TopicExchange(BUSINESS,true,false);var dlx=new TopicExchange(DLX,true,false);var dispatch=QueueBuilder.durable(DISPATCH).quorum().deadLetterExchange(DLX).deadLetterRoutingKey("dead.dispatch").build();var dead=QueueBuilder.durable("dpwfms.integration.dlq").quorum().build();return new Declarables(business,dlx,dispatch,dead,BindingBuilder.bind(dispatch).to(business).with("job.dispatch.command"),BindingBuilder.bind(dead).to(dlx).with("dead.#"));} }
